//! SeaORM entity definitions for every configuration table.
//!
//! Ports the SQLAlchemy `DeclarativeBase` models in `server/db`. Each
//! `mod` below is one table; the `Model` struct is the row type and the
//! `ActiveModel` (generated by `DeriveEntityModel`) is the insert/update type.
//!
//! JSON columns use SeaORM's `Json<T>` value type (the `with-json` feature),
//! which serialises to TEXT on SQLite/MySQL and JSONB on Postgres — matching
//! how the Python code stores JSON. Booleans are native `bool`.
//!
//! The `template_schema_settings.default` column collides with the SQL
//! `DEFAULT` keyword; it is mapped with an explicit `column_name` so the
//! generated DDL quotes it correctly per backend.

pub mod user {
    use sea_orm::entity::prelude::*;

    #[sea_orm::model]
    #[derive(Clone, Debug, PartialEq, DeriveEntityModel)]
    #[sea_orm(table_name = "users")]
    pub struct Model {
        #[sea_orm(primary_key)]
        pub username: String,
        #[sea_orm(default_value = false)]
        pub is_admin: bool,
        #[sea_orm(default_value = false)]
        pub is_sso: bool,
        pub settings: Option<Json>,
        pub password_hash: Option<String>,
        pub sso_groups: Option<Json>,
        pub roles: Option<Json>,
        pub permissions: Option<Json>,
        pub groups: Option<Json>,
    }

    #[async_trait::async_trait]
    impl ActiveModelBehavior for ActiveModel {}
}

