pub mod template_schema_setting {
    use sea_orm::entity::prelude::*;

    #[sea_orm::model]
    #[derive(Clone, Debug, PartialEq, DeriveEntityModel)]
    #[sea_orm(table_name = "template_schema_settings")]
    pub struct Model {
        #[sea_orm(primary_key)]
        pub name: String,
        #[sea_orm(default_value = 0)]
        pub sort_order: i32,
        #[sea_orm(default_value = "")]
        pub label: String,
        #[sea_orm(default_value = "")]
        pub description: String,
        #[sea_orm(default_value = "general")]
        pub category: String,
        #[sea_orm(default_value = "text")]
        pub type_: String,
        // `default` is a reserved SQL keyword; map it explicitly so the DDL
        // quotes the identifier on every backend.
        #[sea_orm(column_name = "default", default_value = "")]
        pub default: String,
        pub current: Option<String>,
        #[sea_orm(default_value = false)]
        pub docker: bool,
        #[sea_orm(default_value = "[]")]
        pub options: Json,
    }

    #[async_trait::async_trait]
    impl ActiveModelBehavior for ActiveModel {}
}

